from lib import *
S = SS('h31')
steps = [
    step("每个正在处理中的调用,服务端多出几个 goroutine:服务端放在子进程里,1000 个调用分在 10 条连接上,全部阻塞在 handler 里。unary、server-stream、bidi 三种,基线都是 2 个 goroutine,在途时都是 1032 个(每个调用 +1.03),全部结束后回到 2 个。也就是说每个调用占一个 goroutine(handler 所在的),多出的 32 个是 10 条连接带的 goroutine(我的推断:每条连接约 3 个,没有逐个核对)。读源码:每个新流默认 go f() 起一个 goroutine(server.go:handleStream)。调用结束 goroutine 就退出,没有残留。", t=tl(S(1)), done=lidx(S(1), 'bidi'), mark=lidx(S(1), 'unary'), b=bars([['基线 goroutine 数', 2, '2'], ['1000 个在途调用时', 1032, '1032'], ['全部结束后', 2, '2']], 1100, mark=[1], done=[0, 2]), kv=KV([['每个在途调用', '约 1 个 goroutine'], ['三种调用类型', '都一样(+1.03)'], ['结束后', '回到基线']], ['每个在途调用'])),
    step("每个在途的 unary 调用占多少内存(服务端子进程里 runtime.GC 之后读 HeapAlloc、StackInuse 的增量):1000 个在途调用:堆 +3.1 KiB/个,goroutine 栈 +8.6 KiB/个,合计 11.7 KiB/个,进程向系统申请的总量(Sys)+17.8 KiB/个;10000 个在途调用:堆 +2.7 KiB/个,栈 +8.1 KiB/个,合计 10.7 KiB/个,Sys +11.7 KiB/个,goroutine 数 2 → 10032。所以每个“挂着”的调用大约 11 KiB(其中栈占大头);一万个挂起的调用约 105 MiB 的量级(10.7 KiB × 10000 ÷ 1024 ≈ 104.5 MiB,是上面的数字相乘得到的估算)。这只是服务端框架本身的开销,不含 handler 里自己分配的东西。", t=tl(S(2)), done=lidx(S(2), '10000 个在途调用'), mark=lidx(S(2), '1000 个在途调用'), b=bars([['1000 个:每个调用合计 KiB', 11.7, '11.7'], ['10000 个:每个调用合计 KiB', 10.7, '10.7'], ['10000 个:栈 KiB/个', 8.1, '8.1'], ['10000 个:堆 KiB/个', 2.7, '2.7']], 13, mark=[1], done=[0, 2, 3]), kv=KV([['堆', '约 3 KiB/个'], ['goroutine 栈', '约 8 KiB/个'], ['合计', '约 11 KiB/个']], ['合计'])),
    step("限制处理中的调用数:5000 个调用同时到达、handler 各睡 20 ms。不限制:同时在处理的峰值 4539,总耗时 68.9 ms;拦截器里加信号量(100):峰值 100,总耗时 1099.9 ms(5000/100 批 × 约 20 ms,加上排队开销);grpc.NumStreamWorkers(8):峰值 4993,总耗时 57.9 ms——这个选项并没有限制并发:读源码 server.go,所有 worker 都忙时会回退到“新开 goroutine”(“If all stream workers are busy, fallback to the default code path”)。它是为了复用 goroutine 栈、减少创建开销,不是用来限流的;要限流用信号量、MaxConcurrentStreams(每条连接)或者负载均衡层。", t=tl(S(3)), done=lidx(S(3), 'NumStreamWorkers(8)'), mark=lidx(S(3), '不限制'), b=bars([['不限制:峰值', 4539, '4539'], ['信号量 100:峰值', 100, '100'], ['NumStreamWorkers(8):峰值', 4993, '4993']], 5100, mark=[0, 2], done=[1]), kv=KV([['不限制', '峰值 4539,68.9 ms'], ['信号量 100', '峰值 100,1099.9 ms'], ['NumStreamWorkers(8)', '峰值 4993:worker 忙时回退到新 goroutine']], ['NumStreamWorkers(8)'])),
    step("客户端取消之后,不看 ctx 的 handler 还在跑:500 个调用的 handler 睡 3 秒,客户端 100 ms 后取消。取消前在运行 500 个;handler 用 time.Sleep(不看 ctx):取消后 500 ms 仍有 500 个在运行,goroutine 比基线多 500;3.5 秒后才降到 0;handler 用 select 同时监听 ctx.Done():取消后 500 ms 就是 0 个在运行、goroutine +0。取消只是让 ctx 变成 Done,不会打断 handler;handler 要自己配合(在等待、下游调用里传递并检查 ctx),否则取消后服务端的资源仍被占着,过载时会越积越多。", t=tl(S(4)), done=lidx(S(4), 'handler 用 select 监听 ctx'), mark=lidx(S(4), 'handler 不看 ctx'), b=bars([['不看 ctx:取消后 500 ms 仍在运行', 500, '500'], ['监听 ctx:取消后 500 ms 仍在运行', 0, '0']], 550, mark=[0], done=[1]), kv=KV([['不看 ctx', '取消后还要跑完 3 秒'], ['select 监听 ctx', '取消后立即退出'], ['含义', '取消不会强制打断 handler']], ['含义'])),
]
A = mkarth('h31', 31, 'gRPC,goroutine,内存,并发,NumStreamWorkers,ctx 取消,Go,真实验证,动画演示',
    '实测 grpc-go 服务端每个在途调用:1 个 goroutine、约 11 KiB(堆约 3 KiB + 栈约 8 KiB);NumStreamWorkers 在 worker 忙时仍新开 goroutine,不能限流,信号量可以;不看 ctx 的 handler 在客户端取消后仍占着 goroutine。',
    'grpc-go 服务端给每个请求起一个 goroutine,这有多贵?一万个挂着的请求占多少内存?NumStreamWorkers 能限流吗?客户端取消了,服务端的 handler 会不会停?这篇用子进程里的纯服务端和真实的 MemStats 回答。',
    [('约 11 KiB', '每个在途的 unary 调用在服务端的开销:堆约 3 KiB + goroutine 栈约 8 KiB'), ('峰值 4993', 'NumStreamWorkers(8) 时 5000 个并发调用同时在处理的峰值——没有限流'), ('500 → 0', '取消后 500 ms 仍在运行的 handler 数:不看 ctx 是 500,监听 ctx 是 0')],
    [('一调用一 goroutine', '<p>grpc-go 服务端默认给每个新流起一个 goroutine 跑 handler,结束就退出。goroutine 本身便宜,但一万个挂起的调用也是一万个 goroutine 和它们的栈。</p>'),
     ('内存', '<p>实测每个挂着的调用约 11 KiB(堆约 3 KiB,栈约 8 KiB),不含 handler 自己的分配。</p>'),
     ('限流', '<p>NumStreamWorkers 是一个 goroutine 复用的优化,worker 忙时仍会新开 goroutine,不能限制并发。真要限流用信号量拦截器、每条连接的 MaxConcurrentStreams 或上游限流。</p>'),
     ('取消', '<p>客户端取消只是让 ctx 变成 Done。handler 要自己在等待和下游调用里监听 ctx;不看 ctx 的 handler 会继续占着 goroutine 直到自然结束。</p>')],
    steps,
    [ENV_H + '。第一、二节的服务端是子进程(只做服务端),runtime.NumGoroutine 与 MemStats(HeapAlloc、StackInuse、Sys,GC 之后)由子进程自己报告,客户端的内存不计入;第三、四节在同一个进程里,峰值用 handler 里的原子计数器;“新流默认 go f()”“worker 忙时回退”读自 server.go',
     '没有验证:handler 里分配更多内存时的情形;GOMAXPROCS 或 CPU 核数对大量 goroutine 调度的影响;流式 RPC 里 goroutine 的数量(每个流一个 handler goroutine 之外是否还有别的,只看了总数);客户端侧每个调用的开销;GC 压力与延迟尾部(第 36 篇压测)'],
    'goroutine 与内存')
